    [10518]={name="Parachute Cloak",quality=2,ilvl=45,sourceType="profession",instructions="Crafted with Engineering (requires skill 1).",profession="Engineering",reqSkills={{"Engineering",225}},proc="Use: Reduces your fall speed for 10 sec. (30 Min Cooldown)"},
