    [22690]={name="Leggings of the Plague Hunter",quality=3,ilvl=66,reqLevel=55,sourceType="quest_reward",instructions="Reward from the quest 'Superior Armaments of Battle - Friend of the Dawn'. Pick it over the other reward choices. Starts with Quartermaster Miranda Breechlock in Eastern Plaguelands. Objective: For 30 Insignias of the Dawn and 30 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.",zone="Eastern Plaguelands",questName="Superior Armaments of Battle - Friend of the Dawn",lore="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power? I must warn you; purchases made at a friendly reputation with the Dawn come with a hefty surcharge.",proc="Equip: Improves your chance to get a critical strike by 1.0%."},
    [22701]={name="Polar Leggings",quality=4,ilvl=80,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Only Song I Know...'. Pick it over the other reward choices. Starts with Craftsman Wilhelm in Eastern Plaguelands. Objective: Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 2 Frozen Runes, 2 Essence of Water, 2 Blue Sapphires and 30 gold pieces.",zone="Naxxramas",questName="The Only Song I Know...",lore="You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?"},
    [22702]={name="Icy Scale Leggings",quality=4,ilvl=80,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Only Song I Know...'. Pick it over the other reward choices. Starts with Craftsman Wilhelm in Eastern Plaguelands. Objective: Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 2 Frozen Runes, 2 Essence of Water, 2 Blue Sapphires and 30 gold pieces.",zone="Naxxramas",questName="The Only Song I Know...",lore="You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?"},
    [22732]={name="Mark of C'Thun",quality=4,ilvl=88,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped.",proc="Equip: Increases your chance to Dodge an attack by 1.0%."},
    [22947]={name="Pendant of Forgotten Names",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Maexxna.",zone="Naxxramas",npc="Maexxna",lore="A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs."},
    [22961]={name="Band of Reanimation",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Patchwerk.",zone="Naxxramas",npc="Patchwerk",lore="An abomination stitched together from the Scourge's leftovers, built for nothing but raw strength."},
    [23023]={name="Sadist's Collar",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Gothik the Harvester.",zone="Naxxramas",npc="Gothik the Harvester",lore="Razuvious's colleague in the Military Quarter, who fights from behind his own dead and keeps sending them forward.",proc="Equip: Improves your chance to get a critical strike by 1.0%."},
    [23027]={name="Warmth of Forgiveness",quality=4,ilvl=85,reqLevel=60,sourceType="object_drop",instructions="Found in Bottle of Disease.",zone="Ashenvale",npc="Bottle of Disease",proc="Use: Restores 500 mana. (3 Min Cooldown)"},
    [23033]={name="Icy Scale Coif",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Heigan the Unclean.",zone="Naxxramas",npc="Heigan the Unclean",lore="Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."},
    [23037]={name="Ring of Spiritual Fervor",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Loatheb.",zone="Naxxramas",npc="Loatheb",lore="A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."},
    [23038]={name="Band of Unnatural Forces",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Loatheb.",zone="Naxxramas",npc="Loatheb",lore="A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand.",proc="Equip: Improves your chance to hit by 1.0%."},
    [23041]={name="Slayer's Crest",quality=4,ilvl=90,reqLevel=60,sourceType="boss_drop",instructions="Drops from Sapphiron.",zone="Eastern Plaguelands",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber.",proc="Use: Increases Attack Power by 260 for 20 sec. (2 Min Cooldown)"},
